 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    rt = [(rb[i]+1, rb[i+1]) for i in range(len(rb)-1)]
    ct = [(cb[i]+1, cb[i+1]) for i in range(len(cb)-1)]
    out = [row[:] for row in grid]
    tiles=[]
    for ri,(a,b) in enumerate(rt):
        for ci,(x,y) in enumerate(ct):
            if b>a and y>x:
                cells=[grid[r][c] for r in range(a,b) for c in range(x,y)]
                tiles.append((sum(v != bg for v in cells),ri,ci))
    if not tiles: return out
    _,sri,sci=max(tiles)
    a,b=rt[sri]; x,y=ct[sci]
    source=[grid[r][x:y] for r in range(a,b)]
    for ri,(r0,r1) in enumerate(rt):
        for ci,(c0,c1) in enumerate(ct):
            if ri==sri and ci==sci: continue
            if r1-r0!=len(source) or c1-c0!=len(source[0]): continue
            if all(grid[r][c]==bg for r in range(r0,r1) for c in range(c0,c1)):
                for i in range(len(source)):
                    for j in range(len(source[0])): out[r0+i][c0+j]=source[i][j]
    return out

if __name__ == '__main__':
